1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioResult = {
13	  results: StepResult[];
14	};
15	
16	const BASE_PREMIUMS = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	} as const satisfies Record<string, number>;
24	
25	const INSURANCE_VALUES = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	} as const satisfies Record<keyof typeof BASE_PREMIUMS, number>;
33	
34	type InsurableItemType = keyof typeof BASE_PREMIUMS;
35	
36	type Item = {
37	  type: InsurableItemType;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type QuoteStep = {
44	  op: "quote";
45	  items: Item[];
46	};
47	
48	type Damage = {
49	  itemType: string;
50	  amount: number;
51	};
52	
53	type Incident = {
54	  cause: string;
55	  damages: Damage[];
56	};
57	
58	type ClaimStep = {
59	  op: "claim";
60	  policy: number;
61	  incident: Incident;
62	};
63	
64	type Step = QuoteStep | ClaimStep;
65	
66	type Customer = {
67	  yearsWithMHPCO: number;
68	};
69	
70	type Scenario = {
71	  customer: Customer;
72	  steps: Step[];
73	};
74	
75	const PROCESSING_FEE = 5;
76	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
80	const LOYALTY_THRESHOLD_YEARS = 2;
81	const LOYALTY_DISCOUNT_PERCENT = 20;
82	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
83	
84	const percentOf = (amount: number, percent: number): number =>
85	  (amount * percent) / 100;
86	
87	// The MHPCO always rounds in its own favour: premiums (which the customer
88	// pays) round up, payouts (which it pays out) round down.
89	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
90	
91	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
92	
93	// Exactly this many components of the same type form a "building block",
94	// priced as a unit rather than per item.
95	const BUILDING_BLOCK_SIZE = 3;
96	const BUILDING_BLOCK_BASE_PREMIUM = 60;
97	
98	const sumOf = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
102	
103	const alikeItemGroups = (items: Item[]): Item[][] =>
104	  insurableItemTypes
105	    .map((type) => items.filter((item) => item.type === type))
106	    .filter((alikeItems) => alikeItems.length > 0);
107	
108	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
109	  alikeItems.length === BUILDING_BLOCK_SIZE;
110	
111	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
112	  formsBuildingBlock(alikeItems)
113	    ? BUILDING_BLOCK_BASE_PREMIUM
114	    : sumOf(alikeItems.map(itemBasePremiumOf));
115	
116	const policyBasePremiumOf = (items: Item[]): number =>
117	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
118	
119	const isCursed = (item: Item): boolean => item.cursed === true;
120	
121	// An item without an enchantment counts as enchantment 0 everywhere.
122	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
123	
124	const isHighlyEnchanted = (item: Item): boolean =>
125	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
126	
127	// A modifier adjusts a base premium by a percentage of it, when it applies to
128	// the subject it is about (an item, a contract, ...). A surcharge has a
129	// positive percent, a discount a negative one, so they all combine by summing.
130	// Modifiers are cumulative: every applicable one applies.
131	type Modifier<Subject> = {
132	  appliesTo: (subject: Subject) => boolean;
133	  percent: number;
134	};
135	
136	const modifierTotalOf = <Subject>(
137	  modifiers: Modifier<Subject>[],
138	  subject: Subject,
139	  basePremium: number,
140	): number =>
141	  sumOf(
142	    modifiers
143	      .filter((modifier) => modifier.appliesTo(subject))
144	      .map((modifier) => percentOf(basePremium, modifier.percent)),
145	  );
146	
147	const ITEM_MODIFIERS: Modifier<Item>[] = [
148	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
149	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
150	];
151	
152	// Item-specific modifiers apply to the base premium of the affected item.
153	const itemModifierTotalOf = (item: Item): number =>
154	  modifierTotalOf(ITEM_MODIFIERS, item, itemBasePremiumOf(item));
155	
156	const isLongStanding = (customer: Customer): boolean =>
157	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
158	
159	// A contract is one quote within a scenario; contractIndex is zero-based, so
160	// every contract after the first is a follow-up.
161	type Contract = {
162	  customer: Customer;
163	  contractIndex: number;
164	};
165	
166	const isFollowUpContract = (contract: Contract): boolean =>
167	  contract.contractIndex > 0;
168	
169	// Policy-wide modifiers apply to the policy base premium and are about the
170	// contract as a whole rather than any single item.
171	const alwaysApplies = (): boolean => true;
172	
173	const POLICY_MODIFIERS: Modifier<Contract>[] = [
174	  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
175	  {
176	    appliesTo: (contract) => isLongStanding(contract.customer),
177	    percent: -LOYALTY_DISCOUNT_PERCENT,
178	  },
179	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
180	];
181	
182	const policyModifierTotalOf = (
183	  contract: Contract,
184	  policyBasePremium: number,
185	): number => modifierTotalOf(POLICY_MODIFIERS, contract, policyBasePremium);
186	
187	const quote = (step: QuoteStep, contract: Contract): QuoteResult => {
188	  const policyBasePremium = policyBasePremiumOf(step.items);
189	  const itemModifiers = sumOf(step.items.map(itemModifierTotalOf));
190	  const policyModifiers = policyModifierTotalOf(contract, policyBasePremium);
191	
192	  return {
193	    premium: roundedUpInMHPCOsFavour(
194	      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
195	    ),
196	  };
197	};
198	
199	const DEDUCTIBLE_PER_DAMAGE = 100;
200	const CAP_MULTIPLIER = 2;
201	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
202	const PARTIAL_REIMBURSEMENT_PERCENT = 50;
203	
204	const roundedDownInMHPCOsFavour = (payout: number): number =>
205	  Math.floor(payout);
206	
207	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];
208	
209	// A policy is created by a quote step and remembers how much of its cap the
210	// customer has already claimed.
211	type Policy = {
212	  items: Item[];
213	  remainingCap: number;
214	};
215	
216	const isReimbursedInPart = (item: Item): boolean =>
217	  enchantmentOf(item) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
218	
219	// The reimbursement clauses decide how much of the damage is covered; the
220	// deductible is then withheld from that amount.
221	const reimbursementOf = (damage: Damage, item: Item): number =>
222	  isReimbursedInPart(item)
223	    ? percentOf(damage.amount, PARTIAL_REIMBURSEMENT_PERCENT)
224	    : damage.amount;
225	
226	const damagePayoutOf = (damage: Damage, item: Item): number =>
227	  reimbursementOf(damage, item) - DEDUCTIBLE_PER_DAMAGE;
228	
229	// The insured item a damage entry is about.
230	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
231	  policy.items.find((item) => item.type === damage.itemType)!;
232	
233	const incidentPayoutOf = (incident: Incident, policy: Policy): number =>
234	  roundedDownInMHPCOsFavour(
235	    sumOf(
236	      incident.damages.map((damage) =>
237	        damagePayoutOf(damage, damagedItemIn(policy, damage)),
238	      ),
239	    ),
240	  );
241	
242	// The total payout per policy is capped, so a claim can only draw what the cap
243	// still holds.
244	const drawnFromCap = (desiredPayout: number, policy: Policy): number =>
245	  Math.min(desiredPayout, policy.remainingCap);
246	
247	// Claiming draws the payout from the policy's remaining cap, so it yields both
248	// the result and the policy as it stands afterwards, rather than mutating.
249	const claim = (
250	  step: ClaimStep,
251	  policy: Policy,
252	): { result: ClaimResult; policy: Policy } => {
253	  const payout = drawnFromCap(incidentPayoutOf(step.incident, policy), policy);
254	  const remainingCap = policy.remainingCap - payout;
255	
256	  return {
257	    result: { payout, remainingCap },
258	    policy: { ...policy, remainingCap },
259	  };
260	};
261	
262	const policyFor = (items: Item[]): Policy => ({
263	  items,
264	  remainingCap: CAP_MULTIPLIER * sumOf(items.map(insuranceValueOf)),
265	});
266	
267	// A scenario is processed step by step: each step produces a result and may
268	// leave behind policies the later steps claim against. Policies are keyed by
269	// the index of the quote step that created them, which is how claim steps
270	// refer to them.
271	type Office = {
272	  policies: Map<number, Policy>;
273	  results: StepResult[];
274	};
275	
276	const emptyOffice = (): Office => ({ policies: new Map(), results: [] });
277	
278	// The scenario arrives as untyped JSON, so the item types it names have to be
279	// checked against the MHPCO's price list before anything is priced.
280	const assertInsurable = (item: Item): void => {
281	  if (!(item.type in BASE_PREMIUMS)) {
282	    throw new Error(`unknown item type: ${item.type}`);
283	  }
284	};
285	
286	// Every step yields its result plus the policy it wrote, under the key that
287	// later steps use to find it.
288	type StepOutcome = {
289	  result: StepResult;
290	  policyKey: number;
291	  policy: Policy;
292	};
293	
294	const withOutcomeRecorded = (office: Office, outcome: StepOutcome): Office => ({
295	  policies: new Map(office.policies).set(outcome.policyKey, outcome.policy),
296	  results: [...office.results, outcome.result],
297	});
298	
299	const outcomeOf = (
300	  office: Office,
301	  step: Step,
302	  stepIndex: number,
303	  customer: Customer,
304	): StepOutcome => {
305	  if (step.op === "quote") {
306	    step.items.forEach(assertInsurable);
307	    const contract = { customer, contractIndex: office.policies.size };
308	
309	    return {
310	      result: quote(step, contract),
311	      policyKey: stepIndex,
312	      policy: policyFor(step.items),
313	    };
314	  }
315	
316	  const claimed = claim(step, office.policies.get(step.policy)!);
317	
318	  return {
319	    result: claimed.result,
320	    policyKey: step.policy,
321	    policy: claimed.policy,
322	  };
323	};
324	
325	export const runScenario = (scenario: Scenario): ScenarioResult => {
326	  const office = scenario.steps.reduce(
327	    (office, step, stepIndex) =>
328	      withOutcomeRecorded(
329	        office,
330	        outcomeOf(office, step, stepIndex, scenario.customer),
331	      ),
332	    emptyOffice(),
333	  );
334	
335	  return { results: office.results };
336	};
